      border-radius: 7px;
      padding: 14px 16px;
    }
    .benchmark-header {
      display: flex;
      justify-content: space-between;
      align-items: flex-start;
      margin-bottom: 8px;
      gap: 12px;
    }
    .benchmark-model {
      font-size: 0.85rem;
      font-weight: 700;
      color: var(--text);
    }
    .benchmark-score {
      font-size: 1.5rem;
      font-weight: 800;
      letter-spacing: -0.04em;
      line-height: 1;
      flex-shrink: 0;
    }
    .score-high { color: var(--teal); }
    .score-mid { color: var(--text-secondary); }
    .benchmark-bar-wrap {
      background: var(--border);
      border-radius: 3px;
      height: 5px;
      overflow: hidden;
      margin-bottom: 6px;
    }
    .benchmark-bar {
      height: 100%;
      border-radius: 3px;
      transition: width 1s ease;
    }
    .bar-high { background: var(--teal); }
    .bar-med-high { background: rgba(46,125,140,0.7); }
    .bar-pass { background: var(--text-secondary); }
    .benchmark-note {
      font-size: 0.73rem;
      color: var(--text-secondary);
      line-height: 1.4;
    }
    .passing-line {
      background: var(--surface);
      border: 1px dashed rgba(13,33,55,0.2);
      border-radius: 6px;
      padding: 8px 14px;
      margin-top: 8px;
      font-size: 0.75rem;
      color: var(--text-secondary);
    }
    html.theme-dark .passing-line { border-color: rgba(255,255,255,0.1); }
    .passing-line strong { color: var(--text); font-weight: 600; }

    /* ===== RISKS SECTION ===== */
    .risks-section {}
    .risks-inner {
      margin-top: 14px;
      display: flex;
      flex-direction: column;
      gap: 10px;
    }
    .risk-item {
      background: var(--surface);
      border: 1px solid var(--border);
      border-left: 3px solid var(--amber);
      border-radius: 0 7px 7px 0;
      padding: 12px 16px;
      display: flex;
      gap: 12px;
      align-items: flex-start;
    }
    .risk-icon {
      width: 28px;
      height: 28px;
      flex-shrink: 0;
      background: rgba(232,145,58,0.12);
      border-radius: 6px;
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .risk-content {}
    .risk-title {
      font-size: 0.82rem;
      font-weight: 700;
      color: var(--text);
      margin-bottom: 3px;
    }
    .risk-desc {
      font-size: 0.76rem;
      color: var(--text-secondary);
      line-height: 1.45;
    }
    .risk-highlight {
      font-size: 0.72rem;
      font-weight: 700;
      color: var(--amber);
      margin-top: 3px;
      display: block;
    }

    /* ===== CHART SECTION ===== */
    .chart-section {
      grid-column: 1 / -1;
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 8px;
      padding: 20px 24px;
    }
    .chart-container {
      height: 220px;
      margin-top: 14px;
      position: relative;
    }

    /* ===== FRAMEWORK SECTION ===== */
    .framework-section {
      grid-column: 1 / -1;
      background: var(--navy);
      border-radius: 8px;
      padding: 28px 32px;
      margin-top: 4px;
      position: relative;
      overflow: hidden;
    }
    html.theme-dark .framework-section {
      background: rgba(46,125,140,0.08);
      border: 1px solid rgba(46,125,140,0.2);
    }
    .framework-section::before {
      content: '';
      position: absolute;
      top: 0; left: 0; right: 0; bottom: 0;
      background: linear-gradient(120deg, rgba(46,125,140,0.12) 0%, transparent 50%);
      pointer-events: none;
    }
    .framework-section .section-label { color: rgba(46,125,140,0.9); }
    .framework-section .section-label::after { background: rgba(46,125,140,0.25); }
    .framework-title {
      color: #fff;
      font-size: 1.05rem;
      font-weight: 700;
      margin-bottom: 20px;
    }
    html.theme-dark .framework-title { color: var(--text); }
    .framework-steps {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 14px;
    }
    .framework-step {
      background: rgba(255,255,255,0.07);
      border: 1px solid rgba(255,255,255,0.1);
      border-radius: 7px;
      padding: 14px 14px;
      position: relative;
    }
    html.theme-dark .framework-step {
      background: rgba(46,125,140,0.07);
      border-color: rgba(46,125,140,0.15);
    }
    .step-num {
      font-size: 0.65rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      color: rgba(46,125,140,0.9);
      margin-bottom: 8px;
    }
    .step-title {
      font-size: 0.82rem;
      font-weight: 700;
      color: #fff;
      margin-bottom: 6px;
      line-height: 1.25;
    }
    html.theme-dark .step-title { color: var(--text); }
    .step-desc {
      font-size: 0.73rem;
      color: rgba(255,255,255,0.55);
      line-height: 1.45;
    }
    html.theme-dark .step-desc { color: var(--text-secondary); }

    /* ===== FOOTER ===== */
    .poster-footer {
      padding: 24px 56px 0;
      border-top: 1px solid var(--border);
      margin: 32px 0 0;
      display: flex;
      justify-content: space-between;
      align-items: flex-start;
      gap: 24px;
      flex-wrap: wrap;
    }
    .footer-quote {
      font-size: 0.82rem;
      font-style: italic;
      color: var(--text-secondary);
      max-width: 640px;
      line-height: 1.55;
    }
    .footer-quote strong { color: var(--text); font-style: normal; font-weight: 600; }
    .footer-meta {
      text-align: right;
      font-size: 0.68rem;
      color: var(--text-secondary);
      line-height: 1.6;
    }

    /* ===== HORIZONTAL RULE ===== */
    .h-rule {
      height: 1px;
      background: var(--border);
      margin: 0 56px;
    }

    /* ===== SECTION BAND ===== */
    .section-band {
      background: var(--band);
      padding: 30px 56px;
    }

    /* ===== ACCESSIBILITY ===== */
    .skip-link {
      position: absolute; left: -9999px; top: auto;
      width: 1px; height: 1px; overflow: hidden;
      z-index: 10000; padding: 8px 16px;
      background: var(--accent); color: white;
      text-decoration: none; border-radius: 4px;
    }
    .skip-link:focus {
      position: fixed; left: 16px; top: 16px;
      width: auto; height: auto; overflow: visible;
    }

    /* ===== RESPONSIVE ===== */
    @media (max-width: 900px) {
      .content-area { grid-template-columns: 1fr; padding: 24px 28px 0; }
      .overview-inner { grid-template-columns: 1fr 1fr; }
      .metrics-grid { grid-template-columns: 1fr 1fr; }
      .framework-steps { grid-template-columns: 1fr 1fr; }
      .poster-header { padding: 32px 28px 24px; }
      .metrics-band { padding: 24px 28px; }
      .poster-footer { padding: 20px 28px 0; }
      .h-rule { margin: 0 28px; }
      .section-band { padding: 24px 28px; }
      .tension-banner { margin: 24px 28px 0; }
    }
    @media (max-width: 600px) {
      .overview-inner { grid-template-columns: 1fr; }
      .framework-steps { grid-template-columns: 1fr; }
      .metrics-grid { grid-template-columns: 1fr 1fr; }
      h1 { font-size: 1.7rem; }
      .metric-value { font-size: 1.8rem; }
      body { overflow-x: hidden; }
    }
    @media (max-width: 375px) {
      body { overflow-x: hidden; }
      .metrics-grid { grid-template-columns: 1fr; }
      .content-area { padding: 16px; }
    }
  </style>
</head>
<body>

  <a href="#main-content" class="skip-link">Skip to content</a>

  <!-- MENU -->
  <div class="viz-menu">
    <button class="viz-menu-toggle" onclick="toggleMenu()" aria-label="Menu">
      <svg width="20" height="20" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">
