    var chartsBuilt = false;

    function getChartColors() {
      var isDark = document.documentElement.classList.contains('theme-dark');
      return {
        text: isDark ? '#EDEDED' : '#0d2137',
        textSec: isDark ? '#888' : '#4a6080',
        border: isDark ? 'rgba(255,255,255,0.07)' : 'rgba(13,33,55,0.10)',
        teal: '#2e7d8c',
        tealAlpha: isDark ? 'rgba(46,125,140,0.65)' : 'rgba(46,125,140,0.72)',
        amber: '#e8913a',
        amberAlpha: 'rgba(232,145,58,0.85)',
        surface: isDark ? '#141414' : '#FFFFFF',
        grid: isDark ? 'rgba(255,255,255,0.04)' : 'rgba(13,33,55,0.06)'
      };
    }

    function resetCanvas(id) {
      var old = document.getElementById(id);
      if (!old) return null;
      var parent = old.parentNode;
      var canvas = document.createElement('canvas');
      canvas.id = id;
      canvas.setAttribute('role', 'img');
      canvas.setAttribute('aria-label', 'Benchmark performance vs hallucination risk comparison');
      parent.replaceChild(canvas, old);
      return canvas;
    }

    function buildCharts() {
      if (chartsBuilt || typeof Chart === 'undefined') return;
      var c = getChartColors();

      if (window.benchmarkChart) {
        try { window.benchmarkChart.destroy(); } catch(e) {}
      }

      var canvas = resetCanvas('benchmarkChart');
      if (!canvas) return;

      window.benchmarkChart = new Chart(canvas, {
        type: 'bar',
        data: {
          labels: ['GPT-4\n(USMLE)', 'Med-PaLM 2\n(MedQA)', 'GPT-3.5\n(USMLE)', 'Hallucination\nRate (LLMs)'],
          datasets: [
            {
              label: 'Score / Rate (%)',
              data: [91, 86.5, 60, 30],
              backgroundColor: [c.tealAlpha, c.tealAlpha, 'rgba(74,96,128,0.5)', c.amberAlpha],
              borderColor: [c.teal, c.teal, c.textSec, c.amber],
              borderWidth: 1.5,
              borderRadius: 4,
              borderSkipped: false,
            }
          ]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          animation: false,
          layout: { padding: { top: 16, right: 16, bottom: 8, left: 8 } },
          plugins: {
            legend: { display: false },
            tooltip: {
              enabled: true,
              padding: 12,
              cornerRadius: 8,
              titleFont: { size: 13, weight: '600', family: 'Inter' },
              bodyFont: { size: 12, family: 'Inter' },
              callbacks: {
                label: function(ctx) {
                  var val = ctx.raw;
                  if (ctx.dataIndex === 3) return ' Hallucination rate: up to ' + val + '%';
                  return ' Benchmark score: ' + val + '%';
                }
              }
            },
            annotation: {}
          },
          scales: {
            x: {
              ticks: {
                color: c.textSec,
                font: { size: 11, family: 'Inter' },
                maxRotation: 0
              },
              grid: { color: c.grid }
